
function addToCart(product) {
    // 检查商品是否已经存在于购物车中
    var existingItem = simpleCart.find(function(item) {
        return item.get('id') === product.id;
    });

    if (existingItem) {
        // 如果商品已存在，增加数量
        existingItem.set('quantity', existingItem.get('quantity') + 1);
    } else {
        // 如果商品不存在，添加到购物车
        simpleCart.add({
            id: product.id,
            name: product.name,
            price: product.price,
            quantity: 1
        });
    }
}
